import json
from pathlib import Path
ROOT=Path(__file__).parent
rows=[]
def p(n,works,assets,fmt,pillar,goal,title,caption,idea,why,order,new,archive=False,sound='none',production='',check=''):
    rows.append(dict(n=n,phase=1 if n<=30 else 2,works=works.split(),assets=assets.split(),format=fmt,pillar=pillar,goal=goal,title_en=title,caption_en=caption,idea_tr=idea,why_tr=why,order_tr=order,new_value_tr=new,archive=archive,sound=sound,production_tr=production or 'Belirtilen özgün arşiv görsellerinden hazırlanacak; fotoğraf hareketli üretim kaydı diye sunulmayacak.',check_tr=check or {'G1':'Takipçi dışı erişim ile varsa gönderiye atfedilen takibi aynı ölçüm yaşında birlikte kaydet.','G2':'Yorumlarda gösterilen biçimsel ilişkiye ilişkin somut gözlemleri kaydet; yalnız beğeniyle tanınma sonucu çıkarma.','G3':'Kaydetme/erişim ve esere özgü farklı kişi sorularını kaydet; yorum yoksa ilgi yok hükmü verme.','G4':'Gönderiden izlenebiliyorsa seçki/portföy ziyareti ve gerçek eser bilgisi talebini ayrı kaydet.'}[goal],tactics=(['T03','T43','T46'] if fmt=='Reel' else ['T54','T55'] if fmt=='Carousel' else ['T23','T50'])+(['T14'] if goal in ['G1','G4'] else ['T56']),evidence='Yerel kaynak auditindeki eser grubu ve seçilen dosyalar; künye için works.json. Biçimsel ilişki editoryal yorumdur.'))

p(1,'angora','A1632 A1378','Reel','space','G1','That dragon is standing over my childhood home.','That is the house I grew up in. A familiar visitor changes the feeling of the place.','Gerçek anlatıdan çocukluk evi ve ziyaret/tehdit ikiliği; ilk karede kendi resmindeki ev ve figür, ardından anlatıcı ve resim birlikte.','Kişisel bağlamı kayıtta bulunan güçlü bir karşılaşma; resim, izleyiciye yalnız karakter tanımaktan fazla bir şey sunar.','Açılışta soyut manifesto yerine üst vizyonun mekân/bellek ayağını tek somut resimle kanıtlar; P002 aynı pratiği beden yönünden genişletecek.','İlk karşılaşma: kayıttaki ev bilgisi ve resimdeki kurmaca ziyaretçi.',sound='english_voice',production='A1632 196–224,308–364,616–644 saniye anlatım dayanağı. Yeni İngilizce ses kaydı gerekli; özgün ağız hareketine İngilizce dublajmış gibi senkron iddiası yok.',check='Karaktere ilişkin tepkiler ile eve/resme ilişkin soruları ayır; takipçi dışı erişim ve atfedilen takip birlikte okunur.')
p(2,'gary','A0298','Single','body','G2','gary grills cooper','A figure assembled from coloured masses, with a cigar above and a grill below.','Bütünü tek görselde, kesmeden; yüz, oval beden, el ve ızgara aynı kompozisyonda okunur.','İlk Reel’in kültürel karakterine bağımlı bir hesap olmadığını, bedenin resimsel kuruluşunu gösterir.','P001 mekânından bedene geçer; P003 bu oval kütlelerin altı yıl önceki farklı bir karşılığını getirecek.','Farklı eserde ortak ressam dilinin ilk kanıtı; Angora yeniden yayımlanmıyor.')
p(3,'cellular','A1862','Single','body','G2','cellular spleens · 2020','A body built from rounded forms, balanced above a car. From the Milan archive, 2020.','Tam eser; araç, üst üste yuvarlak biçimler ve açık zemin birlikte kalır.','Y06 kartının Gary/Y05 ile kurduğu kütlesel beden bağı, hesabın yalnız güncel popüler referanslardan oluşmadığını gösterir.','Gary’nin yuvarlak bedeni ile açık biçimsel bağ kurar; hafta sonunda arşiv bir dolgu değil bu bağı sınayan ikinci eser olur.','2020 tarihli ayrı kompozisyonda hacim dili; etkilenme veya ilerleme hikâyesi iddia edilmez.',True)
p(4,'sept','A1167 A0947','Reel','body','G1','This figure was not always purple.','A yellow figure became purple while the green room remained around it. A recorded painting session from sept neuf.','Gerçek fırça kaydındaki sarı–mor değişimi göster; başlangıç, renk müdahalesi, değişmiş figür. Fotoğraf slaytı yok.','İlk haftadaki bitmiş biçimlerin gerçekten alınan kararlardan oluştuğunu görünür eylemle kanıtlar.','P003’te sonucu gördük; şimdi başka bir resimde bedenin değişmesini izliyoruz. P005 bitmiş yüzlerin farklı kuruluşuna dönecek.','Canlı süreçte bir renk değişimi; Angora’daki sözlü hikâyeden farklı bir Reel işi.',sound='none',production='A1167 gerçek ham oturumdan hareketli parçalar; kaynak zamanları ilk14 paketinde. Arka plandaki medya sesi kullanılmaz; İngilizce vurgu metni, müzik yok.')
p(5,'painstaking','A0025 A0028 A0029 A0027','Carousel','body','G3','Three faces, three different balances.','Three panels, three ways of arranging a face. Read them together, then separately.','Dört sayfa: doğru sıradaki bütün triptik; sol panelin eğik ağız hattı; orta panelin göz/diş yoğunluğu; sağ panelin uzun burun/ağız ağırlığı.','Yüzleri aynı şablonun üç kopyası yerine farklı parça dengeleri olarak karşılaştırmaya elverişli.','Sept’te tek bedenin değişiminden üç ayrı bitmiş çözüme geçer; P006 çizginin benzer işi renk öncesinde nasıl yaptığını açacak.','Painstaking ilk kez ve tek yayın olarak gelir; panel karşılaştırması yeni bilgi, beş güne yayılmış tekrar değil.')
p(6,'ciao','A1718','Single','body','G3','Before the blue: a drawing stage.','Black contours establish two figures before the later blue and white painting. Study image undated; the final painting is from 2020.','Gerçek konturlu ara aşamayı tek görsel olarak sun; son resim görüntüsü ve künye bu dosyaya yapıştırılmaz.','P005’te görülen yüz/beden kuruluşuna farklı dönemden çizgisel bir karşılık; seçilmiş eskiz kendi başına okunuyor.','İki haftayı tamamlar: kişisel mekân → kütle → arşiv bağı → boyama kararı → yüz karşılaştırması → çizim. Sonraki hafta stüdyo kararının konuşmasına açılır.','Bitmiş 2020 eseri yerine tarihsiz ara aşama; konturun rengi beklemeden kurduğu beden.',True)
p(7,'board','A0620 A0592','Reel','scene','G1','What would you leave alone?','The pieces could become darker. The background was already working. A studio conversation around 7 fam board game.','İki kişinin gerçek incelemesi; koyulaştırılacak piyonlar ve korunacak arka plan karşı karşıya.','Her yaratıcı kararı ekleme olarak göstermeyen, gerçek bir stüdyo ikilemi var.','P006 erken çizimden şimdi müdahalenin nerede durduğuna geçer; P008 bitmiş mekân sınırını görünür kılar.','Kaynak sahne anlatmak yerine gerçek karşılıklı geri bildirim.',sound='english_voice',production='A0620 28–84sn kaynak konuşma dayanağı; çeviri uyarlaması için yeni İngilizce ses. Otomatik döküm son ses kontrolünde doğrulanır.')
p(8,'virgil','A0582','Single','space','G2','Virgil on Virtual Cage','Soft bodies sit inside a room drawn with hard white edges.','Bütünü sun; beyaz mekân kenarları, pembe çevre ve yumuşak figürler birlikte görülsün.','Beden ve geometri karşıtlığı, hesabın mekân ayağını Angora dışında ikinci işle kurar.','Board konuşmasındaki arka plan kararından çizilmiş çevrenin etkin olduğu başka sahneye; P009 arşivdeki geometrik nesneye bağlanır.','Yeni eser: çevreleyen çizgi ile beden karşıtlığı.')
p(9,'capricorn','A1832','Single','space','G2','caprocorn sister · 2020','Three bodies share a dark field with a green geometric seat. From the Milan archive, 2020.','2020 bütününü koyu son zeminle göster; üç beden ve geometrik nesne korunur.','Araştırmadaki Y08–Y10 bağını kendi kaynaklarıyla görünür yapar.','Virgil’in çevreleyen kutusuna bir önceki dönemin geometrik nesne/beden karşılığı; sonraki hafta daha geniş sahneye geçiş.','Son koyu zeminli tam eser; ilerideki gerçek boyama kaydından farklı kanıt.',True)
p(10,'mandarin','A0192 A0135 A0136 A0141','Carousel','scene','G1','Above the boat, the scene pulls in another direction.','A row of figures gathers below a field of flying forms. The boat and the upper movement pull the painting in different directions.','Bütün→üstte uçan mavi formlar→alttaki tekne/figür sırası. Detayların doğru konusu görüntüde işaretlenerek seçilir.','Tek bir yüz yerine sahnedeki iki hareket düzeni geniş giriş sunar; kendi resminde cevabı var.','Capricorn’un durağan üçlüsünden hareketli kolektif sahneye geçer; P011 bu kalabalığı tek belirsiz bedene karşılaştırır.','Sahnenin üst/alt yön ilişkisi; mitolojik kaynak hikâyesi henüz anlatılmıyor.')
p(11,'stlop','A0134','Single','body','G2','s(t)lop','A figure emerges through pale strokes, with a red mouth holding its place.','Tam eser; figür ile açık renkli alanın karışması tek görüntüde.','Gary’nin ayrılmış oval parçalarına karşı daha eriyen bir beden çözümü; ressamın aralığını genişletir.','Mandarin’in ayrılabilen figürlerinden figür/zemin sınırı daha belirsiz olan işe geçer; P012 çizimde başka bir yaratığın sınırlarını gösterir.','Yeni eser; tanıdık karakter anlatmadan da aynı hesap vaadi çalışıyor.')
p(12,'wings','A2795','Single','body','G3','A creature in lines.','An undated drawing from the wings of abyss archive. The drawing is shown as a study, rather than the finished painting.','Kök eskizi tam sayfa; kâğıt notlarını dekoratif slogan gibi yeniden yazmadan koru.','Yaratığın çizim halinde nasıl kurulduğu STLOP’un boya içinde beliren bedenine gerçek karşılık verir.','P011 boya sınırının ardından çizgi sınırı; sonraki hafta gerçek boyama hareketine geçmek için erken aşama durak.','Daha önce gösterilmemiş çalışma çizimi; bitmiş eserin yılı eskize atanmaz.',True)
p(13,'capricorn','A2802 A1832','Reel','body','G1','Watch the lower figure change.','Recorded painting footage from caprocorn sister. The final dark background belongs to a later state, beyond the change shown here.','Hızlandırılmış gerçek kayıtta alt figürde siyah alanın büyümesi; sonunda daha sonraki bütün ayrı etiketle.','Kaynakta görünen dönüşüm hareket izleme nedeni yaratır; sonuca sahte kesintisiz süreç atfedilmez.','P012 çizim durağından gerçek yüzey eylemine; P014 bu aşağıda taşınan/bükülen beden ilgisini grup düzenine taşır.','P009 tamamlanmış kompozisyondan farklı olarak tek boyama müdahalesinin gerçek kaydı.',True,production='A2802 120sn editin alt figürde müdahale taşıyan bölümü; kaynak60–100sn aday pencere, son kurgu öncesi hareket seçimi. A1832 later completed state etiketiyle.')
p(14,'gxd','A1209','Single','scene','G2','Gxd is AFK, We banned it','A carried body sits beneath a large dark field, held inside a group of different gestures.','Tam eserde taşıyan, taşınan ve yükselen eller bir arada.','Sahne sütununa farklı bir grup ilişkisi ekler; kaynak isimleri olmadan resmin kendisi incelenir.','Capricorn’un alt bedeninden taşıma düzenine geçer; P015 kolektif gerilimi tek figür ve nesneye daraltır.','Bu eserin ilk bütün sunumu; albüm/ressam referansı sonraki ayrı içerik işi.')
p(15,'wall','A0258','Single','body','G2','walls of perception','A yellow stream connects the face to the bowl below.','Bütün; şapka, yüz, sarı akış ve kırmızı masa.','Figürün sınırını nesneye bağlayan görünür motif beden sütununa farklı bir çözüm ekler.','Gxd’de bedenler arası bağdan tek beden ile kap arasındaki bağa; P016 bu kez figürün çevresinin nasıl boyandığını gösterecek.','Yeni eserde ağız–nesne bağlantısı; psikolojik niyet atfedilmez.')
p(16,'sept','A1159 A0947','Reel','space','G1','Painting the room before filling the figure.','Green paint builds a room around a figure left white. A recorded early session from sept neuf.','Yeşil zeminin beyaz siluetin çevresine boyandığı gerçek el/fırça görüntüsü; boş kalan bedenin kompozisyondaki yerini göster.','Beden yalnız kendisine sürülen boyayla değil çevresinin kurulmasıyla da beliriyor; hareketle anlaşılır.','Wall’da sınırın dışarı akışından çevrenin bedeni ayırmasına geçer; P017 fiziksel tuval ölçeğini tanıtır.','P004 renk değişiminin yerine erken negatif alan kararı; farklı oturum, farklı soru.',production='A1159 beyaz tuval→yeşil zemin kaydı; yalnız gerçekten fırçanın kadrajda olduğu bölüm. Arka plan sesi kapalı.')
p(17,'penguin','A2757 A2743','Carousel','space','G4','A painting at its actual scale.','penguin is not a friend, only a sinner, 2023. A 120 × 120 cm painting, shown beside a person and then on its own.','Gerçek kişiyle ölçek fotoğrafı, ardından düzeltilmiş bütün; dekoratif sahte oda ekleme.','Telefon ekranında eşit görünen resimleri fiziksel nesne olarak incelemeye açar; 2023 arşivine gerçek giriş.','Boyama eyleminden bu eylemin gerçekleştiği nesnenin büyüklüğüne; P018 küçük panellerdeki yüze dönerek ölçek çeşitliliğini kurar.','Yeni dönem ve gerçek ölçek kaydı; arşiv yalnız 2020’yle sınırlı değil.',True)
p(18,'painstaking','A0015 A0019 A0018 A0025','Carousel','body','G3','The eyes do not balance the same way.','Across the three faces, the eyes pull against different mouths and contours.','Göz ayrıntılarını doğru panele bağlayan küçük yer gösterimi; sonunda bütün triptik.','İlk panel karşılaştırmasından sonra yüzü tanımayı sağlayan belirli parçanın dengesini inceletir.','P017 geniş yüzeyden küçük panel içindeki yoğunluğa; P019 başka dönemin tek karikatür bedenine geçer.','P005 panel bütünleri yerine göz–ağız eksenindeki somut fark; yanlış panel eşleştirmesi yapılmaz.')
p(19,'unemployed','A2388','Single','body','G2','cute but unemployed cartoon figure · 2020','A green-grey figure stands against red, its rounded body interrupted by pointed teeth.','Efektsiz bütün; dişler, yuvarlak beden ve kırmızı fon aynı görüntüde.','Tanıdıklık/bedensel bozulma ilişkisini başka eski karakterle genişletir; yalnız Gary’ye dayanmaz.','Painstaking’in gözlerinden tek figürün sivri ağız/yuvarlak gövde karşıtlığına; P020 gündelik nesnelerin kimliği nasıl sabitlediğini açacak.','İlk kez ayrı arşiv eseri, farklı kırmızı/yeşil çözüm.',True)
p(20,'gary','A0298 A0289 A0296 A0293','Carousel','scene','G3','The cigar, the match, the grill.','Three small objects keep an unstable body inside an ordinary scene.','Bütün ve üç nesneye bağlanan detaylar; puro, kibrit/eller, ızgara.','Beden bozulsa da gündelik hareketi okunur kılan nesneleri gösterir; biçimsel yorum görüntüyle denetlenebilir.','P019 belirsiz karakterden Gary’nin tanınabilir gündelik eylemine geçer; P021 Angora’da okunmayı sağlayan mimari yapıyı ele alır.','P002 gövde kütlelerinden nesnelerin sahne kurma işine geçiş; sadece yeni crop değil.')
p(21,'angora','A1554 A1564 A1559','Carousel','space','G3','The house takes shape.','Three recorded stages: the drawn structure, a painted middle state, and the completed scene.','Aynı perspektife oturtulmuş üç gerçek aşama; çizimdeki çatı/geçit düzeninin boyalı kütleye dönüşümü.','Kişisel hikâyeyi bu kez gerçek resim yapısıyla destekler; mevcut düzgün process kaynağını doğru formatta kullanır.','Gary’nin nesnelerle sahne kurmasından mimari kütlelerin sahne kurmasına; sonraki yayın başka bir kaynağın resme gelişini anlatacak.','P001 anı anlatısından çizim–boya aşamaları arasındaki yapı farkına geçiş; slayt Reel yapılmaz.')
p(22,'gxd','A1340 A1209','Reel','scene','G1','An album cover was a way into this painting.','An album cover led back to an older composition, and then into this group of painted bodies.','Sanatçının kayıtlı kaynak zinciri; üçüncü taraf görselleri kopyalamadan kendi resmindeki taşıma düzenine dönen anlatı.','Müzikle ilgilenen kişiye giriş sunar, devamı mevcut resme bağlar.','P021 çizimden resme yolun ardından burada kültürel karşılaşmadan resme yol gelir; P023 başka sahneyi anlatısız inceleme alanı açar.','P014 bütün eser sunumuna daha önce anlatılmayan kaynak ilişkisi eklenir.',sound='english_voice',production='A1340 56–196sn anlatı dayanağı; isimleri ASR’dan körlemesine kopyalama. Yeni İngilizce anlatım gerekir; çekilmiş Türkçe konuşma İngilizceymiş gibi gösterilmez.')
p(23,'board','A0592','Single','scene','G3','7 fam board game','Two facing figures meet across a board filled with smaller bodies.','Bitmiş eser tek görsel; yatay kompozisyon korunur.','Sahnenin tamamına kesintisiz bakış, daha önceki stüdyo kararı videosunda görünmeyen ilişkileri inceleme fırsatı.','Gxd’de taşıma grubundan yüz yüze karşılaşmaya; P024 bu çoklu beden ilişkisini eski çizime taşır.','P007 konuşması yerine tamamlanmış iki taraf ve aradaki küçük bedenler; aynı sesin tekrar yayını değil.')
p(24,'good','A0004','Single','scene','G3','A study for connected bodies.','An undated study from the good people helping bad ones archive.','Karakalem çalışma bütünü; erken çizimi bitmiş akrilik eserden ayır.','Çoklu figür ilişkilerinin eski taslaktaki kuruluşu, stüdyo konuşması ve bitmiş grup resimleriyle ilişki kurar.','Board’daki iki taraf/küçük beden düzeninden arşivde bağlantılı figür taslağına; P025 mekân içindeki nesneye daralma.','Yeni arşiv çizimi; nihai 2019 tarihini çizim tarihine taşımıyor.',True)
p(25,'virgil','A0582 A0502 A0504','Carousel','space','G3','A chair inside a drawn room.','The hanging chair and the white corner make the room legible beside the softer bodies.','Bütün, asılı sandalye, çizgili köşe; her detayın bütün içindeki yeri küçük işaretle.','Mekânın soyut çerçeveden nesneye geçtiği iki görünür kanıt var.','Çizimden çevreleyen çizgilerin bitmiş odasına; P026 başka dönemde çizgisel sandalye karşılığı.','P008 genel kutu/beden karşıtlığından belirli sandalye ve köşe okumaya geçer.')
p(26,'peachy','A2156','Single','space','G2','The body bends; the chair stays drawn.','An elongated body bends through a purple-blue field beside a chair drawn in white. From 2019.','Yatay bütün, eğilen beden ve beyaz sandalye korunur.','Virgil’deki sandalye üzerine arşivde farklı bir beden–mobilya düzeni getirir.','P025’teki nesne/çerçeve sorusunun 2019 karşılığı; P027 dikey asılı figürü başka sahnede genişletir.','Yeni arşiv işi; benzer nesne üzerinden fark gösterir, gelişim sırası iddiası yok.',True)
p(27,'mandarin','A0211 A0214 A0218','Carousel','scene','G3','How the scene gathers around the boat.','Recorded stages of articulo attack on mandarin: a drawn arrangement becomes a painted scene.','Hazır hizalanmış çizim/orta/son aşama; tekne–üst hareket ilişkisini taşıyan kompozisyonu takip et.','P010’daki hareket ayrımının süreçte nasıl yer tuttuğunu incelemek için ek kanıt.','Peachy’de tek asılı bedenin ardından kalabalık yerleştirmeye; P028 gerçek boyama görüntüsüyle kütlenin kuruluşuna geçer.','P010 bitmiş üst/alt karşıtlığı yerine kayıtlı aşamalar; aynı montajın hız varyantı değil.')
p(28,'board','A0630 A0592','Reel','body','G1','Building the red body.','A recorded session from 7 fam board game: the red figure develops through actual brushwork.','Kırmızı gövde üzerinde gerçek fırça hareketi; geniş hareket ve elin değiştirdiği yer birlikte.','Konuşmanın dışında yapılan işin kendisi yeni izleyici için anlaşılır eylem sunar.','Mandarin aşama fotoğraflarından kesintisiz fiziksel harekete; P029 boya yapma eyleminden eski çoklu beden sonucuna geçer.','P007 karar konuşması ve P023 bütününden farklı olarak gerçek kırmızı boya müdahalesi.',production='A0630 kırmızı gövde ham oturumu. Yeni video icat edilmez; kesim noktaları bu uzun vadeli kartın üretim aşamasında seçilecek. Arka plan medyası kapalı.')
p(29,'baby','A1809','Single','body','G2','baby rights 101 · 2020','Black and white bodies fold through each other, crossed by thin red lines.','Tam eser; iç içe figürler ve ince kırmızı çizgiler korunur.','Sıcak kırmızı kütleye karşı ağırlıkla siyah/beyaz ve çizgisel bağ kuran önceki dönem çözümü.','P028’de tek kırmızı beden kurulurken burada beden sınırları birlikte katlanır; P030 ilk dönemin üç alanını toparlar.','Yeni arşiv eseri; farklı malzeme dili değil aynı medium içinde farklı çizgi/alan ilişkisi.',True)
p(30,'angora gary sept','A1378 A0298 A0947','Carousel','space','G4','Three ways into the paintings.','A house, a body, a room. Three paintings from 2026, with their titles, materials and dimensions.','Üç eser her biri ayrı sayfada doğru künye; son sayfa güncel seçkinin doğrulanmış bağlantısına yön.','Yeni gelenin hesabı tek eser üzerinden okumamasını sağlayan kısa, kullanılabilir portföy girişi.','İlk29 gönderinin mekân/beden/sahne kanıtını üç okunur esere toplar; ikinci bölüm bu vaatlerin içindeki somut kararları daha yakından açacak.','Rastgele best-of değil, bu dönemde gösterilmiş üç inceleme yolunun künyeli eşleştirmesi.')

p(31,'stlop','A0134 A0096 A0097','Carousel','body','G3','A mouth holds the figure together.','Pale strokes blur the edge of the figure; the red mouth gives the eye a place to return.','Bütün, yüz/alt yüz; resimdeki kırmızı ağızla çevresindeki açık izlerin karşıtlığını göster.','İlk tanışıklığı tek gözle denetlenebilir inceleme kararına dönüştürür.','P030 geniş seçkiden bir resimdeki tek tutunma noktasına; P032 başka bedende küçük nesnenin benzer işi nasıl yaptığını açar.','P011 genel bütün sunumundan ağız–zemin bağlantısına geçiş.')
p(32,'cellular','A1862','Carousel','body','G3','The small car changes the size of the body.','The car beneath the figure changes how large the rounded body feels. cellular spleens, 2020.','Bütün ve aynı dosyadan araç/bacak bölümü; sayfada önce ölçek etkisi sonra bütüne dönük işaret.','Aracın sadece ek motif değil beden ölçeğini okumaya yarayan karşılık olduğunu gösterir.','STLOP’ta ağız tanınmayı sabitlerken burada araç boyut algısını değiştirir; P033 bu kütlelerin yeni bir resimde kuruluşuna geçer.','P003 oval kütle benzerliğinden araç ile bedenin orantı ilişkisine; farklı ve somut soru.',True)
p(33,'gary','A0340 A0350 A0298','Carousel','body','G3','A figure before and after its coloured masses.','The line structure and the painted body offer two different ways of reading the same figure.','Çizim ve boyalı süreç dosyalarını adlarındaki aşama numarasına göre doğrula; iki aşama ve son bütün.','Yuvarlak kütlelerin sırf figür konusu değil resim kurma kararı olduğunu kayıtlı aşamayla gösterir.','P032 bitmiş eski kütleden Gary’nin çizgi–kütle ayrımına; P034 tam kapanmayan konturun başka karşılığını getirir.','P002 sonuç ve P020 nesnelerden farklı olarak gerçek çizim/renk aşaması. Referans fotoğrafı süreç diye gösterilmez.')
p(34,'sept','A1165 A0947','Reel','body','G1','A contour can stay visible through a body.','Light lines keep moving across the purple figure and the chair. Recorded work on sept neuf.','Açık/mavi kontur üzerinde gerçek boyama; çizginin tamamlanmış gövde boyunca nasıl okunduğunu son karede göster.','Harekette görülen açık çizgi, bedenin kapalı bir renk lekesi olmamasını anlatır.','Gary’de dolan hacimden Sept’te açık kalan kontura; P035 eski çift yüzün silinen sınırlarıyla karşılaştırma.','P004 renk değişimi/P016 zemin ayrımı yerine açık çizgi ilişkisi.',production='A1165 açık/mavi konturlar ham oturumu; yalnız çizgiyle ilgili görünen müdahale. Şimdiden kesin saniye aralığı seçilmiş sayılmaz; üretimde hareket eşleştirilecek.')
p(35,'duality','A1945','Single','body','G2','duality of the angelic summarization · 2019','A bearded face, another small figure, and a body that fades into its surroundings.','Tam eser, çift yüz/beden silinmeleri ve küçük figür ilişkisi.','Açık sınırın eski bir işte farklı, daha silinen karşılığını gösterir.','P034 çizginin görünür devamından burada gövdenin çevreye karışmasına; P036 daha keskin yüz parçalarına dönülür.','İlk arşiv bütün sunumu; benzerlik kadar sınır farkı da görünür.',True)
p(36,'painstaking','A0029 A0027 A0025','Carousel','body','G3','Teeth in one face, a heavy mouth in another.','The centre panel gathers its teeth into a tight field. The right panel gives more weight to the mouth and nose.','Orta ve sağ panel tam; küçük konum göstergesi; son bütün.','Yüzdeki ağız parçalarının iki farklı ağırlık kurduğunu kanıtlayan doğrudan karşılaştırma.','Duality’de eriyen yüz kenarından Painstaking’de ağız parçalarının yoğunluğuna; P037 ağırlığı bütün bedenin taşınmasına büyütür.','P018 göz ekseni yerine diş alanı ve burun/ağız ağırlığı; ayrı inceleme iddiası.')
p(37,'gxd','A1209','Carousel','scene','G3','Where does the weight go?','The carried body leans into the group, while the raised hands pull the eye upwards.','Bütün→taşınan beden/taşıyıcı→açılan eller; kendi görselinde yönleri hafif çizgiyle göster, yeni şekil ekleme.','Taşıma sahnesinde bedenin ağırlığı ve bakışın yönü ayrılabilir görünür kanıtlar.','P036 yüz içindeki ağırlıktan figürler arası yük ilişkisine; P038 ters asılı bedenle bu yönü sınar.','P022 kaynak zinciri yerine kendi kompozisyonundaki yük/yön ilişkisi.')
p(38,'guard','A2050','Single','scene','G2','guarding holy mountains from malice · 2019','An inverted red figure hangs above a group of blue figures and a broad pink mass.','Tam yatay sahne; ters kırmızı figürle aşağıdaki grup birlikte.','Yük ve yön sorusunun eski sahnede asılmasının farklı bir karşılığını verir.','Gxd’de taşınandan burada ters asılana; P039 küçük figürün büyük figürle merkez kurmasına geçer.','Yeni arşiv sahnesi; iş başlığından siyasi/kişisel niyet çıkarılmaz.',True)
p(39,'virgil','A0582 A0499 A0501','Carousel','scene','G3','A smaller body changes the centre.','The smaller figures change how the central body meets the room around it.','Bütün ve çocuk/küçük figür detayları; çevredeki figürlerin ana gövdeye göre yerlerini açıkça koru.','İlk mekân okumasını grup ilişkisine genişletir; aynı kutunun içinde farklı inceleme görevi.','P038 grubun yukarı/aşağı düzeninden merkezi büyük ve küçük bedenlerin ilişkisine; P040 tek büyük yaratığın farklı ölçü düzeni.','P025 sandalye/köşeden çocuk/küçük figürün grup içindeki yerine geçiş. Fotoğraflar carousel, sahte ham video yok.')
p(40,'wings','A2451','Single','body','G3','wings of abyss · 2019','A pointed white head and a spiralling body sit below an inverted pink figure.','Tamamlanmış bütün ilk kez; P012 eskizini tekrar slayta dönüştürmeden resim kendi başına.','Eskizdeki biçimlerin tamamlanmış resimde renk ve yön kazanmasını görme fırsatı.','Virgil’de küçük/büyük beden karşıtlığından burada terslik ve spiral gövdeye; P041 sahnede yönlerin çoğalmasına.','P012 yalnız eskizdi; bu yayın bitmiş eserin yeni renk/yön kanıtını sunar.',True)
p(41,'mandarin','A0192','Carousel','scene','G3','A vertical figure between two horizontal worlds.','The hanging figure cuts through the distance between the upper forms and the boat below.','Bütün ve merkezdeki ince direk/asılı figürü kapsayan crop; üst/alt gruplar konum haritasında görünür.','İlk üst/alt karşıtlığını bu iki alanı bağlayan üçüncü eksenle genişletir.','Wings’te ters asılı bedenin ardından asılı figürün sahne bağlama görevine; P042 mimari bakış yönünü açar.','P010 üst/alt/P027 süreçten farklı olarak dikey bağlantı ve asılı figür.')
p(42,'angora','A1632 A1378','Reel','space','G1','Why show the house from above?','The elevated view exposes roofs, walls and passages at once. The house takes an active part in the scene.','Sanatçının izometrik bakış anlatımı ve kendi bütününde çatı/cephelerin aynı anda okunması.','Mekânı figür kadar etkin yapan somut bakış seçimini görünür kılar.','Mandarin’de dikey sahne ekseninden Angora’da yukarıdan bakışa; P043 çizgiden renk alanına başka yapıyı kurar.','P001 çocukluk bilgisi ve P021 süreçten ayrı perspektif sorusu.',sound='english_voice',production='A1632 224–252 ve364–420sn izometrik kompozisyon anlatısı; yeni İngilizce ses. 3B referansları gerçek resim yapma anı olarak gösterme.')
p(43,'wall','A0260 A0262 A0264','Carousel','body','G3','The face, the table, the space between.','Recorded stages of walls of perception: a figure and a table become connected by paint.','Gerçek üç aşama; aradaki sarı akışın boyalı kompozisyonda yerleşmesini aşamalarla incelet.','Tek motifin çizim ve boya arasında nasıl yer tuttuğunu gerçek kayıtla destekler.','P042 bakış açısının kurduğu mekândan burada iki form arasındaki boyalı bağlantıya; P044 parçalı yüzün arşiv karşılığı.','P015 bitmiş sarı bağın yerine gerçek aşamalar; efekt varyantı kullanılmaz.')
p(44,'rompi','A1750','Single','body','G2','il sbagliato di rompipalle · 2019','A fragmented face and a toothed form emerge from purple and yellow against green.','Bütün eser; yüzün parçaları ile yeşil alanın farkını koru.','Güncel yüz seçkisinin daha eski, farklı renk ve diş çözümünü getirir.','Wall’un yüz-nesne akışından Rompi’nin yüz içinde kırılan düzenine; P045 stüdyoda sahneyi bir arada tutma çalışması.','İlk arşiv sunumu; Painstaking’in kaynağı olduğu iddia edilmez.',True)
p(45,'board','A0631 A0592','Reel','scene','G1','Painting with the paper beside the canvas.','A recorded studio session shows painting and paper references sharing the same working space.','Gerçek kayıtta kâğıt referans ile tuvale bakma/çalışma hareketi; basılı kaynağın ne olduğunu teyitsiz adlandırma.','Üretimin yalnız fırçanın tuvale dokunması değil bakma ve karar verme olduğunu görünür eylemle gösterir.','P044 bitmiş kırılmadan sahneyi bir arada tutmaya çalışan stüdyo hareketine; P046 eski kağıt eseri sunar.','P007 sohbet/P028 kırmızı boya yerine bakışın kâğıt ve tuval arasında dolaşması.',production='A0631 ilk49dk içinden kâğıtla görünen çalışma; son49–57dk boş atölye elenir. Türkçe ortam medyası kullanılmaz.')
p(46,'good','A2014','Single','scene','G3','good people helping bad ones · 2019','Large pale forms meet smaller orange figures on black paper.','Bütün eser, siyah kâğıt mediumu açıkça belirtilir.','P024 çizim ailesinin tamamlanmış renk ve boyut karşılığını gösterir; kâğıt eserin maddi bilgisi de yeni.','Board’da kâğıt referansla üretimden burada kâğıdın bitmiş eserin zemini oluşuna; P047 diğer çizim/boya bağı.','Önceki tarihsiz eskizden ayrı, 2019 bitmiş akrilik/kâğıt eser.',True)
p(47,'gxd','A1335 A1319 A1323 A1209','Carousel','scene','G3','The group before the dark field.','A drawing, a recorded painted stage, and the completed group show different states of the same composition.','Temiz taslak, boyalı ara aşama, son bütün; karanlık fonun grup çevresindeki payına bak.','Kaynak hikâyesinin ötesinde kendi çiziminden kendi resmine somut bir karar yolu.','P046 siyah kâğıdın açık biçimleri taşımasından Gxd’de boyanan koyu alanın grubu taşımasına; P048 küçük el hareketinin sahne kurması.','P022 kaynak/P037 ağırlık yerine çizimden boyalı zemin ilişkisine geçiş.')
p(48,'gary','A0296 A0298','Carousel','scene','G3','The hands keep the action small.','The hands and match hold a small, ordinary action inside a much larger body.','El/kibrit yakın planı ile bütün: işaretli konum ve bedenle orantı, iki sayfa yeterli.','Küçük jestin hacimli gövdeye karşı rolünü somutlaştırır.','Gxd’nin büyük taşıma jestinden gündelik küçük el işine; P049 arşivde yükselen elin farklı hareketine.','P020 üç nesneyi tanımlıyordu; burada el–gövde ölçek farkı ve küçük hareket inceleniyor.')
p(49,'viperella','A1772','Single','body','G2','viperella · 2020','A long purple-pink figure raises one hand against a pale field.','Tam eser; el, uzun beden ve kırmızı dudak aynı kompozisyonda.','Elin küçük gündelik hareket yerine bütün bedenin yönünü belirlediği eski karşılık.','Gary’nin gövdeye yakın ellerinden dışarı yükselen ele; P050 bir el/kuş bakış ilişkisinin bulunduğu odaya.','Yeni eski eser; medya dosyasını sırf video adı var diye Reel saymıyor.',True)
p(50,'sept','A0947','Carousel','space','G3','Two seats, two bodies.','The chair and the bird’s perch create two places to sit inside the green room.','Bütün; insanın kıvrımlı koltuğu ve kuşun çizgisel taburesi ayrı crop, yapı farkı açıklanır.','Aynı odada iki oturma düzeneğinin bedenleri nasıl farklı taşıdığını göstermeye elverişli.','P049 yükselen elin ardından burada yerleşen bedenlerin desteğine; P051 kutu çizgisinin başka destek/sınır görevine.','Önceki renk/boş siluet/kontur videolarından ayrı olarak iki mobilya ve iki beden ilişkisi.')
p(51,'virgil','A0582 A0504 A0505','Carousel','space','G3','A hard corner around soft bodies.','White lines define a corner while the figures remain soft and uneven inside it.','Köşe/zemin detayları ve bütün; geometrik çizgi ile figür kenarının farkı karşılaştırılır.','Mekân sütununun temel biçim karşıtlığını yakın kanıtla inceletir.','Sept’te mobilyanın bedeni taşımasından Virgil’de odanın bedeni çevrelemesine; P052 gerçek boya ile sınır oluşturma hareketi.','P025 nesne/köşe tanımından geometrik köşe ile organik kenarın biçim karşılaştırmasına.')
p(52,'capricorn','A2801 A1832','Reel','body','G1','One continuous passage of painting.','An uninterrupted extract from the caprocorn sister studio recording. The final painting is shown separately at the end.','Hızlandırma yerine tek gerçek kesintisiz fırça geçişi; ortaya çıkan kenarı izlemeye yeterli süre.','Önceki hızlı değişimden farklı olarak kararın ritmini ve el hareketini gözlenebilir kılar.','Virgil’in çizgili sınırından gerçekten boya ile çekilen kenara; P053 mekânda girilebilir boşluklara.','P013 hızlandırılmış dönüşüm yerine tek sürekli hareketin kenar kurma işi; aynı klibin hızını değiştirerek ikinci kaynak icat edilmez.',True,production='A2801 ham üstten kayıt; görünen tek fırça geçişi 12–20sn aday, üretimde seçilecek. P013 ile aynı kaynak ailesi olduğu kayıtlıdır; yeni değer hareketin gerçek süreli incelenmesidir.')
p(53,'angora','A1378 A1408 A1409 A1410','Carousel','space','G3','Ways into the house.','Doors, steps and roof edges divide the house into routes for the eye.','Alt ev, merdiven/geçit ve çatı detayları; fotoğraftaki tuval dışı ahşabı kırp, mimari içeriği koru.','Evin anı olarak değil resimde gezinilen bir yapı olarak somut incelemesi.','P052 çizilen kenardan burada rotayı kuran kenarlara; P054 iki bedenin arasındaki boşluğu getirir.','P001 biyografi/P042 bakış açısı yerine kapı, merdiven ve geçit düzeni.')
p(54,'ciao','A1903','Single','body','G3','ciao capo, sono squalo · 2020','Two elongated blue and white bodies hold their outlines against red and black.','Bitmiş bütün; P006 çiziminden ayrı tarihli tam eser sunumu.','Daha önceki konturlu aşamanın boya ve renk sonrasındaki ayrı okunma fırsatı.','Angora’daki geçit boşluğundan iki bedenin arasındaki ayrılmaya; P055 başka dönemde aşamaların tüm kompozisyonu değiştirmesine.','P006 çizim kırmızı/pale; bu yayın 2020 son mavi/beyaz gövdeleri getirir.',True)
p(55,'penguin','A2740 A2741 A2742 A2743','Carousel','body','G3','Four recorded states of a square painting.','Four recorded states of penguin is not a friend, only a sinner. Painted in 2023.','Dört aynı kadrajlı aşama; her sayfa gerçek durum olarak, canlı boyama filmi diye sunulmadan.','Kare kompozisyonun çizgi/akış ilişkisini zaman içindeki kayıtlarla açar.','Ciao’nun nihai sonucundan burada boyalı durumların farkına; P056 farklı fiziksel bölünme olarak triptiğe.','P017 yalnız gerçek ölçekti; şimdi farklı durumlar arasındaki yüzey düzeni.',True)
p(56,'painstaking','A0025 A0028 A0029 A0027','Carousel','body','G4','One triptych, three separate canvases.','Painstaking is a triptych of three canvases, each 40 × 30 cm. The gaps belong to the arrangement; they are not painted stripes.','Doğru bütün yanında her panelin ayrı tam hali ve 40×30 künye; toplam genişliğe aralık ölçüsü uydurma.','Ekran görüntüsünün tek yatay resim sanılmasını önler; fiziksel eseri incelemeye yarayan doğru bilgi.','Penguin’in tek kare yüzeyinden üç ayrı dikey tuvale; P057 tuval içindeki başka bir fiziksel bağlantıya döner.','P005 biçim karşılaştırması/P018 göz/P036 ağızdan ayrı nesne ve ölçü bilgisi; aynı panellerin tekrar gerekçesi açık.')
p(57,'wall','A0258 A0224 A0225 A0226 A0227','Carousel','body','G3','From mouth to bowl.','The yellow passage crosses the space between a face and an object. Follow where it begins and where it lands.','Dört hazır detaydan akışın başlangıcını ve kapla temasını gösteren ikisini seç; bütünle yerleştir.','Sarı bağın iki uçta nasıl farklı biçim aldığına bakmayı sağlar.','P056 fiziksel panel aralığından burada resim içinde geçilen aralığa; P058 boya sınırlarının son rötuşuna.','P015 bütün/P043 aşamalardan farklı olarak akışın başlangıç ve bitiş biçimlerinin karşılaştırması.')
p(58,'sept','A1172 A0947','Reel','body','G3','The small marks near the end.','A late recorded session from sept neuf: small adjustments around an already established figure.','Son oturumda görünen küçük boya müdahaleleri; genel resmi tekrar anlatmadan elin değiştirdiği bölgeyi yeterince açık göster.','Büyük renk değişimi kadar küçük son kararın da resmin okunmasına katkısını izlenebilir yapar.','Wall’daki belirli uçların ardından Sept’in küçük son düzeltmeleri; P059 başlangıç çizimiyle zaman karşıtlığı kurar.','P004 büyük renk değişiminden ayrı geç evre küçük müdahale. Son fırça darbesi veya tamamlandığı an olduğu iddia edilmez.',production='A1172 rötuş oturumu; somut değişim görünmüyorsa bu slot yeni kaydedilecek eser başında açıklamaya çevrilecek, boş el hareketi yayımlanmayacak.')
p(59,'lucid','A1696','Single','scene','G3','A drawing from the lucid drowning archive.','An undated drawing from the remixed execution of lucid drowning archive, with its working notes still visible.','Çalışma çizimi ve görünür renk notlarını koru; notları sanatçı adına geniş bir hikâyeye çevirmeden.','Bitmiş kararlardan önceki düşünme malzemesine yeni arşiv kapısı açar.','P058 son aşama ile burada ilk taslak arasında anlamlı zaman farkı; P060 dönemler arasındaki ortak kütle dilini özetler.','Bu işin ilk taslak sunumu; 2019 bitmiş resim tarihi çizime atanmaz.',True)
p(60,'gary cellular stlop','A0298 A1862 A0134','Carousel','body','G4','Three bodies, three different edges.','Rounded masses in gary grills cooper and cellular spleens meet a less settled edge in s(t)lop. Three paintings, two periods.','Üç bütün, her birinde kütle ve sınırın tek farkı; son sayfa bu beden seçkisinin doğru künyeleri.','Araştırmanın açık Gary–Cellular–STLOP eşleştirmesini kullanılabilir küçük seçki haline getirir.','İkinci bölümün tek karar incelemelerini bir ilişkiye toplar; P061 yeni kültürel/kavramsal girişlerle aynı pratiğin sahne ayağına geçecek.','P030 genel hesap girişi yerine belirli üç eser ve sınır farkına dayanan beden seçkisi.')

